import { test, expect } from '@playwright/test';

test.describe('File Download on Export Button Click', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/export');
  });

  test('should download file when export button is clicked', async ({ page }) => {
    // Setup download interception
    await page.route('**/api/export', (route) => {
      route.abort();
    });

    // Setup download listener
    const downloadPromise = page.waitForEvent('download');

    // Click export button using getByRole
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();
    await exportButton.click();

    // Wait for download to complete
    const download = await downloadPromise;

    // Verify download file exists
    const fileName = download.suggestedFilename();
    expect(fileName).toContain('export');

    // Verify download is available
    const downloadUrl = download.url();
    expect(downloadUrl).toBeDefined();

    // Verify download progress indicator appears
    const downloadIndicator = page.getByText(/downloading/i);
    await expect(downloadIndicator).toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/export successful/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle API error and display error message when export fails', async ({ page }) => {
    // Setup API error interception
    await page.route('**/api/export', (route) => {
      route.abort();
    });

    // Setup download listener (should not trigger)
    const downloadPromise = page.waitForEvent('download', { timeout: 5000 });

    // Click export button using getByRole
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();
    await exportButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/export failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details are displayed
    const errorDetails = page.getByText(/please try again/i);
    await expect(errorDetails).toBeVisible();

    // Verify download indicator does not appear
    const downloadIndicator = page.getByText(/downloading/i);
    await expect(downloadIndicator).not.toBeVisible();

    // Verify export button is still enabled for retry
    await expect(exportButton).toBeEnabled();
  });
});
